export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ap = u / g, aph = u * u / (2 * g);
  const t = sdk.clamp(time, 0, T);
  const h = Math.max(0, u * t - g * t * t / 2);
  const v = u - g * t;
  const F = m * g;
  let st = 'Falling';
  if (t < 1e-9) st = 'Ready to toss';
  else if (Math.abs(t - ap) < 1e-6) st = 'At the top';
  else if (t < ap) st = 'Rising';
  else if (t >= T - 1e-6) st = 'Back at launch height';
  const y0 = 340, sc = 108;
  const by = y0 - sc * h;
  const vf = (x) => u - g * x;
  const pts = (a, b, n) => { const r = []; for (let i = 0; i <= n; i++) { const x = a + (b - a) * i / n; r.push({ x, y: vf(x) }); } return r; };
  const t0 = Math.max(0, t - 0.15), t1 = Math.min(T, t + 0.15);
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 40, w: 310, h: 360, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 40, w: 300, h: 360, title: 'Velocity over time', state: 'v = u - g t' }));
  o.push(sdk.axis('axis.height', { x: 60, y: y0, length: 238, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  o.push(sdk.circle('ball.toss', 100, by, 28));
  o.push(...sdk.vector('vec.v', { x: 140, y: by }, { value: v, direction: 'up' }, { scale: 11, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 180, y: by }, { value: -g, direction: 'up' }, { scale: 3.5, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(215, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  o.push(sdk.plot('plot.vt', { x: 340, y: 70, w: 280, h: 280, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [
    { label: 'Trace', kind: 'line', points: pts(0, t, 12) },
    { label: 'Continuation', kind: 'line', points: pts(t, T, 12) },
    { label: 'Slope a = -g', kind: 'line', points: pts(t0, t1, 1) }
  ] }));
  o.push(sdk.text('plot.vt.note', 345, 385, 'slope a = -g = ' + sdk.format(-g, 1) + ' m/s²'));
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [
      { id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st } ] },
    quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ap, apexHeight: aph, height: h, velocity: v, acceleration: -g, force: F }
  };
}
